<?php
$id = (string)($_GET['id'] ?? ''); $r = sr_find_record($id);
if (!$r) { sr_hero('Missing record', 'Record not found', 'The requested record ID does not exist in the loaded JSON data.'); echo '<p><a class="button" href="?page=explore">Back to Explore Everything</a></p>'; return; }
sr_hero('Record detail', $r['title'], 'Plain-language owner summary first; complete normalized/raw JSON data is available below.');
?>
<section class="record-layout"><article class="panel primary"><h2>What this item is</h2><p><?= nl2br(sr_e($r['description'])); ?></p><?php if (trim($r['notes']) !== ''): ?><h3>Owner / source notes</h3><p><?= nl2br(sr_e($r['notes'])); ?></p><?php endif; ?><h3>Owner decision gates</h3><ul class="gate-list"><li><b>Public use:</b> <?= sr_e(sr_public_gate($r)); ?></li><li><b>Rights:</b> <?= sr_pill($r['rights_status'], 'risk'); ?></li><li><b>Safety:</b> <?= sr_pill($r['safety_status'], 'risk'); ?></li><li><b>Status:</b> <?= sr_pill($r['status']); ?></li></ul></article><aside class="panel"><h2>Fast facts</h2><dl class="facts"><?php foreach (['record_id'=>'Record ID','timeline_moment_id_or_gen'=>'Timeline / GEN','family'=>'Family','section'=>'Section','category'=>'Category','priority'=>'Priority','owner_or_responsible_role'=>'Owner role','public_private_flag'=>'Public/private','last_updated'=>'Last updated'] as $field=>$label): ?><div><dt><?= sr_e($label); ?></dt><dd><?= sr_e($r[$field]); ?></dd></div><?php endforeach; ?><div><dt>Source JSON</dt><dd><a href="<?= sr_e(sr_source_url($r['source_file'])); ?>"><?= sr_e($r['source_file']); ?></a></dd></div></dl></aside></section>
<section class="panel"><h2>Connected files and records</h2><div class="two-col"><div><h3>Files / sources</h3><ul><?php foreach ($r['linked_files'] as $f): ?><li><?= sr_linked_file($f); ?></li><?php endforeach; ?></ul></div><div><h3>Linked records</h3><ul><?php foreach ($r['linked_records'] as $lr): $found=sr_find_record((string)$lr); ?><li><?= $found ? '<a href="'.sr_e(sr_record_url((string)$lr)).'">'.sr_e((string)$lr).'</a>' : '<a href="'.sr_e(sr_url(['page'=>'explore','q'=>(string)$lr])).'">Search for '.sr_e((string)$lr).'</a> <span class="muted">(not a direct record ID)</span>'; ?></li><?php endforeach; if (!$r['linked_records']) echo '<li class="muted">No linked records listed in JSON.</li>'; ?></ul></div></div></section>
<?php sr_raw_block($r, 'Raw normalized record data'); sr_raw_block($r['raw_record'], 'Original canonical record fragment'); ?>
